INSERT INTO Note VALUES('8855a44a-f3d9-4424-8221-8cebb82abe25','Prompts',replace('Erstell mir bitte ein Wiederholungsquiz zum Thema Technische Informatik. Ich hätte gerne 30 Multiple-Choice-Fragen. \nDas Format sieht so aus: Eine neue Frage beginnt immer mit einem Listenpunkt. Die möglichen Antworten darunter sind mit a), b) etc. bezeichnet. Die erste Antwort ist immer die Richtige.\nFüge zu jeder Frage bitte noch einen Tip hinzu. Füge außerdem eine ausführliche, aber leicht verständliche Erläuterung hinzu.','\n',char(10)),'01ed6e10-397e-446c-9254-2ad7fd4ec777',1,'#4CAF50',2,1753819730280,1754804253899);
