INSERT INTO QuizQuestion VALUES('2b257b37-71d8-4a58-ac33-f883f4326c00','awetgawet','rr','["ggg","ff","t","rr"]','Denke an die elementarste Form von Information in der Digitaltechnik.','Das Bit ist die kleinste Informationseinheit und kann nur die Werte 0 oder 1 annehmen.',1,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894034);
INSERT INTO QuizQuestion VALUES('db0bc8ed-e029-4c28-9bab-e7e8baac749c','Was ist die kleinste Informationseinheit in der Informatik?','Bit','["Bit","Byte","Kilobyte","Wort"]','Erinnere dich an die Standarddefinition von Byte in der Informatik.','Ein Byte besteht aus 8 Bits. Das ist ein weltweit etablierter Standard.',2,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894036);
INSERT INTO QuizQuestion VALUES('e1f89658-455b-4999-8381-021f8def219b','Wie viele Bits enthält ein Byte?','8','["8","4","16","10"]','Rechne jede Binärstelle in eine Zweierpotenz um und addiere sie.','1010₂ = 1·2³ + 0·2² + 1·2¹ + 0·2⁰ = 8 + 0 + 2 + 0 = 10.',3,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894038);
INSERT INTO QuizQuestion VALUES('8b085b38-9457-4223-b44e-624f221f22fd','Welche Zahl entspricht dem Binärwert 1010 im Dezimalsystem?','10','["10","8","12","15"]','Sie wird auch als Prozessor bezeichnet.','Die CPU (Central Processing Unit) ist das „Gehirn“ des Computers und führt Befehle aus.',4,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894039);
INSERT INTO QuizQuestion VALUES('23dd5b30-29cf-412a-90fc-4af3315d3201','Was bezeichnet die CPU in einem Computersystem?','Zentrale Verarbeitungseinheit','["Zentrale Verarbeitungseinheit","Speicherbaustein","Grafikkarte","Netzteil"]','ALU steht für Arithmetic Logic Unit.','Die ALU führt mathematische (Addieren, Subtrahieren) und logische (UND, ODER, NICHT) Operationen aus.',5,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894039);
INSERT INTO QuizQuestion VALUES('c64c4153-a080-4576-9ba4-98e36a76a706','Welche Funktion hat das ALU in der CPU?','Führt arithmetische und logische Operationen aus','["Führt arithmetische und logische Operationen aus","Speichert temporäre Daten","Steuert den Datenfluss zwischen Ein- und Ausgabegeräten","Wandelt analoge Signale in digitale um"]','Digitale Schaltungen arbeiten nur mit zwei Zuständen.','Im Binärsystem gibt es nur 0 und 1 – passend zu den zwei elektrischen Zuständen an/aus.',6,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894040);
INSERT INTO QuizQuestion VALUES('97f536b6-58cc-47fd-80ed-213cb6af726a','Welches Zahlensystem wird in digitalen Schaltungen verwendet?','Binärsystem','["Binärsystem","Dezimalsystem","Hexadezimalsystem","Oktalsystem"]','Überlege, welcher Speicher nur mit Strom funktioniert.','RAM (Random Access Memory) ist flüchtig und verliert seinen Inhalt ohne Stromversorgung.',7,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894041);
INSERT INTO QuizQuestion VALUES('b06d7978-c81b-482f-9c2b-739b6758c671','Welcher Speicher verliert seinen Inhalt nach dem Ausschalten?','RAM','["RAM","ROM","Flash-Speicher","Festplatte"]','Es ist die Negation des UND-Gatters.','Ein NAND-Gatter liefert nur dann 0, wenn beide Eingänge 1 sind, sonst 1.',8,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894041);
INSERT INTO QuizQuestion VALUES('594adfae-2077-44cf-a2fc-a2d33136952c','Welches Logikgatter liefert nur dann 0, wenn beide Eingänge 1 sind?','NAND','["NAND","UND","ODER","XOR"]','OR bedeutet, dass mindestens einer der Eingänge 1 sein muss.','Beim ODER-Gatter ist der Ausgang nur 0, wenn beide Eingänge 0 sind.',9,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894042);
INSERT INTO QuizQuestion VALUES('6e4f14e2-94da-4968-891c-4722f1355ca2','Welche Wahrheitstafel gehört zum ODER-Gatter?','0/0 → 0, alle anderen Kombinationen → 1','["0/0 → 0, alle anderen Kombinationen → 1","Nur 1/1 → 1, sonst 0","Nur unterschiedliche Eingänge → 1","Immer 0, wenn mindestens ein Eingang 0 ist"]','Überlege, ob mindestens einer der Eingänge 1 ist.','0 ODER 1 ergibt 1, weil mindestens ein Eingang wahr ist.',10,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894043);
INSERT INTO QuizQuestion VALUES('f7853367-d77c-47b8-9926-83b9d117335b','Was ergibt die ODER-Verknüpfung von 0 und 1?','1','["1","0","-1","2"]','Es wandelt die Netzspannung in die für den Computer benötigten Spannungen um.','Das Netzteil versorgt alle Komponenten mit der nötigen Spannung.',11,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894044);
INSERT INTO QuizQuestion VALUES('c36fa6be-57f4-4b17-b2db-b762439bd772','Welches Bauteil ist für die Spannungsversorgung eines Computers verantwortlich?','Netzteil','["Netzteil","Mainboard","Prozessor","Arbeitsspeicher"]','Er ist kleiner, aber schneller als der RAM.','Cache-Speicher speichert oft benötigte Daten, um Zugriffe zu beschleunigen.',12,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894045);
INSERT INTO QuizQuestion VALUES('c5914275-f877-43a8-8080-2ce98a4091fc','Wie nennt man den Zwischenspeicher zwischen CPU und RAM?','Cache','["Cache","Register","SSD","Bus"]','Erklärung: Ein Multiplexer leitet das Signal eines von mehreren Eingängen an den Ausgang weiter.','',13,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894045);
INSERT INTO QuizQuestion VALUES('edc795a3-90eb-40d2-bc0d-38f70e0c72e6','Wofür wird ein Multiplexer verwendet?','Auswahl eines von mehreren Eingangssignalen','["Auswahl eines von mehreren Eingangssignalen","Vervielfachung eines Signals","Verstärkung eines Signals","Fehlerkorrektur"]','Hexadezimalzahlen nutzen Ziffern 0–9 und Buchstaben A–F.','Im Hexadezimalsystem steht F für den Wert 15.',14,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894047);
INSERT INTO QuizQuestion VALUES('b08384f1-7c8c-4d6d-b102-580510b90734','Welche Zahl ist im Hexadezimalsystem gleichbedeutend mit der Dezimalzahl 15?','F','["F","E","D","1F"]','Denke an die Geschwindigkeit beim Starten und Laden.','SSDs sind viel schneller, da sie keine beweglichen Teile haben.',15,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894048);
INSERT INTO QuizQuestion VALUES('44140b30-8a90-4446-a2ef-4dd7b548bdf2','Was ist der Hauptvorteil von SSDs gegenüber HDDs?','Schnellere Zugriffszeiten','["Schnellere Zugriffszeiten","Höhere Speicherkapazität","Geringerer Preis pro GB","Mechanische Bauteile"]','Er „übersetzt“ Binärcodes.','Ein Decoder wandelt binäre Codes in genau definierte Ausgänge um.',16,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894048);
INSERT INTO QuizQuestion VALUES('6732b948-6c4d-4591-9738-25fd7204b038','Was macht ein Decoder in der Digitaltechnik?','Wandelt binäre Eingaben in eindeutige Ausgänge um','["Wandelt binäre Eingaben in eindeutige Ausgänge um","Verstärkt das Eingangssignal","Speichert Daten dauerhaft","Mischt mehrere Signale"]','Es funktioniert wie die Schnittmenge zweier Bedingungen.','Das UND-Gatter liefert nur 1, wenn beide Eingänge 1 sind.',17,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894049);
INSERT INTO QuizQuestion VALUES('f6cb4ab6-8e25-433a-8568-bac270bb3d26','Welche Wahrheitstafel beschreibt das UND-Gatter?','Nur bei 1 und 1 ist der Ausgang 1','["Nur bei 1 und 1 ist der Ausgang 1","Nur bei 0 und 0 ist der Ausgang 1","Immer 1, wenn mindestens ein Eingang 1 ist","Immer 0, wenn beide Eingänge gleich sind"]','XOR steht für „exklusives ODER“.','Das XOR-Gatter liefert 1, wenn genau einer der Eingänge 1 ist.',18,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894050);
INSERT INTO QuizQuestion VALUES('f0672ef1-b490-4a74-a808-3f85c2c06ba4','Welche Wahrheitstafel gehört zum XOR-Gatter?','Ausgang = 1 nur bei ungleichen Eingängen','["Ausgang = 1 nur bei ungleichen Eingängen","Ausgang = 1 nur bei beiden Eingängen 1","Ausgang = 0 bei ungleichen Eingängen","Ausgang = 0 nur bei beiden Eingängen 0"]','Er verbindet die verschiedenen Komponenten des Systems.','Ein Bus überträgt Daten, Adressen oder Steuerinformationen zwischen Bauteilen.',19,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894051);
INSERT INTO QuizQuestion VALUES('bab33976-fad7-4994-8242-ad6224ae1d7d','Was ist ein Bus im Computersystem?','Ein System zur Datenübertragung zwischen Komponenten','["Ein System zur Datenübertragung zwischen Komponenten","Ein Speicherbereich im Prozessor","Ein Steuerbefehl im Assembler","Ein Stromversorgungskabel"]','Es ist das ODER mit nachgeschaltetem NICHT.','Das NOR-Gatter liefert nur 1, wenn beide Eingänge 0 sind.',20,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755610894055);
INSERT INTO QuizQuestion VALUES('b299f944-a939-4ce6-abe6-b61e6814c624','Welche Logikfunktion entspricht der Negation von A ODER B?','NOR','["NOR","NAND","XOR","XNOR"]','Es ist das ODER mit nachgeschaltetem NICHT.','Das NOR-Gatter liefert nur 1, wenn beide Eingänge 0 sind.',21,'61a601a9-fdbb-45dd-96a9-dd293e796147',1755580370394,1755580370394);
