INSERT INTO Flashcard VALUES('e8e293d3-957a-44b6-8b20-1091cba19798','10e83a3c-d204-4973-81d9-624165e38f04','Was ist der Unterschied zwischen **operativem** und **strukturellem Verständnis**?','**Operativ** = Regeln anwenden, **strukturell** = Konzepte verstehen.',NULL,1,7,1756033520235,1756033520235);
