INSERT INTO Flashcard VALUES('1dd432b4-1f8d-4f58-bbe7-79001e7d6c03','10e83a3c-d204-4973-81d9-624165e38f04','Welche Rolle spielt **Sprache** im Bruchunterricht?','Präzise Begriffe wie **Zähler** und **Nenner** müssen **aufgebaut** und **gesichert** werden.',NULL,1,11,1756033520238,1756033520238);
INSERT INTO Flashcard VALUES('dc044d08-d275-4f87-85e6-d3f619bfc5de','10e83a3c-d204-4973-81d9-624165e38f04','Welche Bedeutung hat die **Zahlengerade**?','Sie zeigt *Brüche* als **Zahlen zwischen den Ganzen** und verdeutlicht **Größenvergleiche**.',NULL,1,9,1756033520223,1756033520223);
