INSERT INTO Flashcard VALUES('1ee703a0-709c-40b8-a8a6-3844060fbe46','10e83a3c-d204-4973-81d9-624165e38f04','Welche typischen **Fehlvorstellungen** haben Schüler*innen?','Brüche werden als **zwei getrennte Zahlen** gesehen oder **falsch addiert** (z. B. 1/3 + 1/4 = 2/7).',NULL,1,4,1756033520223,1756033520223);
