INSERT INTO Flashcard VALUES('e3b53e01-8f1e-4936-8dde-13aabe9c372f','8de95e7d-bd2a-4774-816f-90746498db66','Warum sind **multiple Repräsentationen** zentral?','Sie unterstützen **Verknüpfungen** zwischen **anschaulichen** und **abstrakten Vorstellungen**.',NULL,1,8,1756062695753,1756062695753);
INSERT INTO Flashcard VALUES('820e0b8c-7980-42c1-a186-7eacbceceb71','8de95e7d-bd2a-4774-816f-90746498db66','Was ist der **Stellenwert von Material** im Unterricht?','Es ermöglicht **handelndes Lernen** und **Konzeptaufbau**.',NULL,1,26,1756062695751,1756062695751);
INSERT INTO Flashcard VALUES('7033bb36-2b86-44eb-98b8-2f4308d8bcb8','8de95e7d-bd2a-4774-816f-90746498db66','Wie lässt sich die *Bruchrechnung* mit **Kompetenzorientierung** verbinden?','Durch **offene Aufgaben**, **Argumentation** und **vielfältige Darstellungen**.',NULL,1,27,1756062695752,1756062695752);
INSERT INTO Flashcard VALUES('6897a01b-80a3-4c80-ab68-6fabc4a814b2','8de95e7d-bd2a-4774-816f-90746498db66','Warum ist der **Teil-Ganzes-Bezug** wichtig?','Er ist **Ausgangspunkt** für das Verständnis von *Brüchen*.',NULL,1,12,1756062695740,1756062695740);
INSERT INTO Flashcard VALUES('a9c9c24a-7af2-4541-a7d2-87b598dc5ab5','8de95e7d-bd2a-4774-816f-90746498db66','Welche Rolle spielt **Sprache** im Bruchunterricht?','Präzise Begriffe wie **Zähler** und **Nenner** müssen **aufgebaut** und **gesichert** werden.',NULL,1,13,1756062695742,1756062695742);
INSERT INTO Flashcard VALUES('3f7aa079-ffb8-4db5-a1b3-c1c4cc1b7c91','8de95e7d-bd2a-4774-816f-90746498db66','Warum ist der **Wechsel** zwischen Darstellungsformen wichtig?','Er fördert **konzeptuelle Flexibilität** und ein **tiefes Verständnis**.',NULL,1,4,1756062695740,1756062695740);
INSERT INTO Flashcard VALUES('3d9324c5-5dcd-4043-a0c8-255b63ce754f','8de95e7d-bd2a-4774-816f-90746498db66','Wie können Lehrkräfte **Fehlvorstellungen** aufgreifen?','Durch **Visualisierungen**, **Kontrastierungen** und **Diskussionen**.',NULL,1,7,1756062695740,1756062695740);
INSERT INTO Flashcard VALUES('c323accd-569d-4f5a-988c-853528fe2c2b','8de95e7d-bd2a-4774-816f-90746498db66','Welche **Darstellungsformen** sind zentral in der Bruchdidaktik?','Vor allem **Flächenmodell**, **Streifenmodell**, **Zahlengerade** und **Alltagskontexte**.',NULL,1,3,1756062695740,1756062695740);
